@startuml

class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + Type : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + Type : string
  + ManufacturingPrice : double
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : string
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" *-- "1..*" Furniture
Furniture "1" *-- "1..*" ComponentType
Furniture "1" -- "0..*" OrderLine
Order "1" -- "1..*" OrderLine
Order "1" -- "1" Store
Store "1" -- "0..*" Order

@enduml

